// Coach hub contract v2: the payload types and topic names every surface builds against.
//
// PURE: no imports and no runtime behaviour beyond a few constants, so this file can be copied
// verbatim into the TV apps (tv/web, tv/vega), the phone page and the simulator. docs/CONTRACT.md
// is the prose; fixtures/contract-v2/*.json are typed examples of these shapes
// (src/hub/contractExamples.ts). Owned by the lead: packets do not edit this file.
//
// Times are epoch milliseconds on the HUB clock (the demo clock in demo mode) unless a field says
// otherwise. Ids are opaque strings.

export const CONTRACT_VERSION = 2 as const;

// The phone's pair token on the /ws upgrade: offered as the WebSocket subprotocols
// [WS_PROTOCOL, WS_TOKEN_PREFIX + base64url(token)], so it never sits in a URL (proxy and tunnel
// access logs). The hub lists only WS_PROTOCOL as selectable (BridgeHub's `protocols`), so it answers
// with WS_PROTOCOL and never with the token, whatever order a client offers them in; a client that
// offers only the token gets no subprotocol back. ?k=<token> still works.
export const WS_PROTOCOL = "speaking-mirror" as const;
export const WS_TOKEN_PREFIX = "k." as const;

// Topics

// v1 sequenced topics (every peer in every room, and SSE).
export const V1_TOPICS = ["session.started", "card.open", "attempt.provisional", "attempt.status", "attempt.verified", "attempt.graded", "stats.updated", "session.ended"] as const;
// v2 sequenced topics (every peer in every room, and SSE, and GET /api/events/recent).
export const V2_TOPICS = ["conversation.started", "live.window", "nudge.sent", "nudge.skipped", "conversation.ended", "recap.ready", "live.mode", "practice.summary", "mirror.focus"] as const;
// Every topic that goes through CoachHub.publish: it gets a `seq` and reaches every surface.
export const SEQUENCED_TOPICS = [...V1_TOPICS, ...V2_TOPICS] as const;
// Room-scoped topics: sent only to the `screen` peers of one bridge room, with no `seq`. Never on
// SSE, never in /api/events/recent, never persisted. CoachHub.publish refuses them.
export const ROOM_TOPICS = ["practice.meters"] as const;
// Sent to one peer when it joins (seq 0), not sequenced.
export const JOIN_TOPIC = "hub.state" as const;
// Topics a bridge client may send to the hub as `{type:"app", topic, payload}`.
export const CLIENT_APP_TOPICS = ["card.request", "attempt.submit", "session.start", "session.next", "session.end", "practice.meters", "practice.summary", "mirror.focus"] as const;

export type V1Topic = (typeof V1_TOPICS)[number];
export type V2Topic = (typeof V2_TOPICS)[number];
export type SequencedTopic = (typeof SEQUENCED_TOPICS)[number];
export type RoomTopic = (typeof ROOM_TOPICS)[number];
export type ClientAppTopic = (typeof CLIENT_APP_TOPICS)[number];

// Rates and limits frozen by the contract.
export const LIVE_WINDOW_MIN_INTERVAL_MS = 3000; // live.window: at most one per 3 s per conversation
export const LIVE_WINDOW_RECENT_MS = 120_000; // LiveWindow.recent counts the last 2 minutes
export const PRACTICE_METERS_HZ = 10; // the phone sends practice.meters at 10 Hz
export const ROOM_RELAY_MAX_HZ = 20; // the hub relays room topics to screens at <= 20 Hz per room
export const WRIST_TEXT_MAX = 60; // wrist (Bee to-do) text, characters
export const RECAP_MOMENT_MAX_WORDS = 12;
export const RECAP_MIN_WEARER_WORDS = 60;

// Common

export type Lang = "en" | "fr";
export interface ErrorBody {
  error: string; // machine code, e.g. "not_implemented", "forbidden", "unknown_recap"
  message: string;
}
export interface Labelled {
  dataLabel: string; // "SYNTHETIC DEMO DATA (...)" in demo mode
  synthetic: boolean;
}

// v1 payloads (unchanged; mirrored here import-free)

export type HabitKind = "filler" | "hedge" | "vague" | "restart" | "trailing" | "yeah-tic" | "error" | "vocab";
export interface Habit {
  kind: HabitKind;
  targets: string[];
  label: string;
}

export interface CardView {
  id: string;
  kind: "error" | "vocab" | "filler";
  lang: Lang;
  type: string;
  habit: Habit;
  said: string;
  fix: string;
  resay: string;
  why: string;
  mustSay: string[];
  box: number;
  due: string;
  dueNow: boolean;
  passes: number;
  fails: number;
  source: { session: string; key: string };
  synthetic: boolean;
}

export interface GradeCheck {
  rule: "nonempty" | "habit" | "fillers" | "content" | "required";
  ok: boolean;
  detail: string;
}
export interface GradeResult {
  graderVersion: number;
  pass: boolean;
  reasons: string[];
  checks: GradeCheck[];
  habit: { kind: HabitKind; label: string; hits: number; found: string[] };
  fillerCount: number;
  fillers: string[];
  hedgeCount: number;
  hedges: string[];
  contentMatch: number;
  contentThreshold: number;
  missing: string[];
  fuzzy: { target: string; heard: string }[];
  required: { word: string; ok: boolean }[];
}

export interface BoxChange {
  from: number;
  to: number;
  dueBefore: string;
  dueAfter: string;
  scheduled: boolean;
}
export interface DeckSummary {
  date: string;
  total: number;
  dueNow: number;
  boxes: Record<string, number>;
  dueByDate: Record<string, number>;
  nextDueDate: string | null;
}

export type ProvisionalSource = "phone" | "alexa" | "mcp" | "typed"; // mcp: an MCP client (the /sim/ simulator, an assistant)
export type AttemptStatus = "pending_bee" | "polling" | "graded" | "unverified";
export type Agreement = "agree" | "bee-overrules" | "bee-only";
export interface Attempt {
  id: string;
  cardId: string;
  sessionId: string | null;
  status: AttemptStatus;
  counted: boolean;
  createdAt: number;
  settledAt: number | null;
  provisional: { source: ProvisionalSource; text: string; speechEndAt: number; grade: GradeResult } | null;
  // spokenFromMs/spokenToMs/conversationId (additive): when Bee's lines were spoken and in which Bee
  // conversation, so the stats can leave the drill lines out of the final transcript too.
  bee: { text: string; gradedText?: string; extraText?: string; utteranceIds: number[]; speakerScore: number | null; via: "stream" | "poll"; latencyMs: number | null; coverage: number | null; replay: boolean; spokenFromMs?: number; spokenToMs?: number; conversationId?: string | null } | null;
  final: { source: "bee"; pass: boolean; grade: GradeResult } | null;
  agreement: Agreement | null;
  reason: string;
  box: BoxChange | null;
  synthetic?: boolean;
  openingSeq?: number; // additive: which opening of the card it was made in (a hub counter, reset on restart)
}

export interface DrillSession {
  id: string;
  by: string;
  startedAt: number;
  endedAt: number | null;
  size: number;
  cardIds: string[];
  attemptIds: string[];
}
export interface SessionSummary {
  sessionId: string;
  by: string;
  startedAt: number;
  endedAt: number | null;
  cards: number;
  attempts: number;
  counted: number;
  passed: number;
  failed: number;
  unverified: number;
  pending: number;
  beeOverrules: number;
  perCard: { cardId: string; habit: string; attempts: number; passed: number; box: number | null; due: string | null }[];
}

export type VoiceState = "idle" | "card_open" | AttemptStatus;
export interface BeeFeedStatus {
  replay: boolean;
  pendingVerifications: number;
  lastEventAt: number | null;
  counters: Record<string, number>;
}
// GET /api/state = GET /api/session (also the hub.state frame, plus seq/at). The HTTP route adds
// lastSessionSummary and currentSessionSummary.
export interface HubState {
  mode: "live" | "demo";
  dataLabel: string;
  // This hub process (new on every start) and the last seq it published when this snapshot was
  // taken. A screen that sees a different bootId knows the hub restarted (seq starts again at 1);
  // events at or below lastSeq are already reflected in the snapshot. Optional: older hubs omit them.
  bootId?: string;
  lastSeq?: number;
  state: VoiceState;
  narration: string;
  verdictReady: boolean;
  retryAfterMs: number | null;
  session: DrillSession | null;
  openCard: CardView | null;
  lastAttempt: Attempt | null;
  deck: DeckSummary;
  // Today's drill tally (the hub's local day) as of this snapshot; stats.updated carries it after,
  // and the hub publishes stats.updated again when the local day turns. Optional: older hubs omit it.
  practiceToday?: PracticeCounts;
  bee: BeeFeedStatus;
}
export interface SessionResponse extends HubState {
  lastSessionSummary: SessionSummary | null;
  currentSessionSummary: SessionSummary | null;
}
// POST /api/attempt (202)
export interface AttemptAccepted {
  attempt: Attempt;
  narration: string;
  verdictUrl: string;
  retryAfterMs: number | null;
}
// GET /api/attempts/<id>
export interface VerdictResponse {
  attempt: Attempt;
  status: AttemptStatus;
  verdictReady: boolean;
  retryAfterMs: number | null;
  narration: string;
}
// POST /api/session/start
export interface SessionStartResponse {
  session: DrillSession;
  card: CardView | null;
  narration: string;
}

export interface Rate {
  count: number;
  per100: number;
  ci95: [number, number];
}
export interface HabitRates {
  words: number;
  lines: number;
  fillers: Rate & { breakdown: Record<string, number> };
  hedges: Rate & { breakdown: Record<string, number> };
  vague: Rate & { breakdown: Record<string, number> };
  restarts: Rate;
  trailingOff: Rate;
  yeahTics: Rate;
}
export type SourceSel = "bee" | "all";
export interface SourceCount {
  sessions: number;
  words: number;
  label: string;
  // The first and last local date of this source's sessions. Additive: older hubs omit them.
  from?: string | null;
  to?: string | null;
}
export interface Period {
  sessions: number;
  words: number;
  count: number;
  per100: number;
  ci95: [number, number];
  from: string | null;
  to: string | null;
}
export interface TalkSummary {
  meetings: number;
  talkShareWords: number | null;
  turns: number;
  substantiveTurns: number;
  avgTurnWords: number;
  longestTurnWords: number;
  questions: number;
  trailingOffSentences: number;
  sentences: number;
}
// GET /api/stats
export interface PracticeCounts {
  attempts: number;
  counted: number;
  passed: number;
  unverified: number;
  beeOverrules: number;
}
export interface StatsResponse {
  dataLabel: string;
  synthetic: boolean;
  range: string;
  source: SourceSel;
  sources: Record<string, SourceCount>;
  sessions: { id: string; kind: "conversation" | "meeting" | "voice_note"; date: string; words: number; synthetic: boolean }[];
  habits: HabitRates;
  talk: TalkSummary | null;
  practice: PracticeCounts | null; // drill attempts in the range; null for session:<id> and meeting:<id> (a conversation is not a drill period)
  drilledVsNextSession: {
    habit: string;
    label: string;
    firstDrillAt: number;
    lastSessionBefore: ({ session: string; date: string } & Period) | null;
    nextSessionAfter: ({ session: string; date: string } & Period) | null;
    deltaPer100: number | null;
    preregistered: boolean;
    note: string;
  }[];
}

export type TransferVerdict = "dropped" | "no change" | "rose" | "too little data" | "not drilled yet" | "invalid";
export interface TransferHabit {
  habit: string;
  label: string;
  role: "drilled" | "control";
  firstDrillAt: number | null;
  cutoverAt: number | null;
  cutoverSource: string;
  before: Period;
  after: Period;
  deltaPer100: number | null;
  verdict: TransferVerdict;
  detail: string;
  wordsNeededPerPeriod: number | null;
}
// GET /api/transfer
export interface TransferResponse {
  dataLabel: string;
  generatedAt: string;
  synthetic: boolean;
  source: SourceSel;
  sources: Record<string, SourceCount>;
  prereg: { path: string; registeredAt: string; drilled: string[]; control: string[]; basis: string };
  minWordsPerPeriod: number;
  method: string;
  habits: TransferHabit[];
  unregistered: { habit: string; drills: number; note: string }[];
  headline: string;
  // What `headline` claims, as a fixed value, so a screen words it without re-deriving it from the
  // verdicts. "...-control-flat" only when every control showed no change; "all-..." when every
  // drilled habit dropped; "dropped-control-unclear" when the controls cannot be compared.
  claim: TransferClaim;
  // The first signal per pre-registered drilled habit that has been drilled: the last conversation
  // before its first drill vs the next one after it. A same-day glance, not the test. Additive:
  // older hubs omit it.
  firstSignal?: FirstSignal[];
}
// FirstSignal.status: "measured" (both conversations have FIRST_SIGNAL_MIN_WORDS words), "too-few-words"
// (one side is shorter: say so, never a number), "no-next-conversation" (none since the drill yet),
// "no-earlier-conversation" (nothing before it to compare).
export const FIRST_SIGNAL_MIN_WORDS = 100;
export type FirstSignalStatus = "measured" | "too-few-words" | "no-next-conversation" | "no-earlier-conversation";
export interface FirstSignalSide {
  session: string;
  date: string; // the hub's local date
  startMs: number;
  words: number;
  count: number;
  per100: number;
}
export interface FirstSignal {
  habit: string;
  label: string;
  firstDrillAt: number;
  status: FirstSignalStatus;
  before: FirstSignalSide | null;
  after: FirstSignalSide | null;
  deltaPer100: number | null; // after - before, only when "measured"
  minWords: number;
  note: string;
}
// GET /api/instrument (additive): Bee and meeting captions on the meetings both heard, as
// aggregates. `agree` per habit is null until the pooled pairs have INSTRUMENT_MIN_WORDS words on
// each side. "practised-agree": the two pre-registered practised habits (hedges, filler:like) are
// within INSTRUMENT_TOLERANCE on both; only then may a screen say captions and Bee agree on them.
export const INSTRUMENT_HABITS = ["hedges", "filler:like", "restart", "um-uh", "fillers"] as const;
export const INSTRUMENT_MIN_WORDS = 200;
export const INSTRUMENT_TOLERANCE = { per100: 0.3, relative: 0.15 } as const;
export const INSTRUMENT_CLAIMS = ["practised-agree", "practised-differ", "too-little-data", "no-pairs"] as const;
export type InstrumentClaim = (typeof INSTRUMENT_CLAIMS)[number];
export interface InstrumentHabit {
  habit: (typeof INSTRUMENT_HABITS)[number]; // a habit key, or "um-uh" ("um" and "uh" together)
  captionsPer100: number;
  beePer100: number;
  agree: boolean | null;
}
export interface InstrumentResponse {
  dataLabel: string;
  synthetic: boolean;
  generatedAt: string;
  pairs: number; // meetings heard by both
  from: string | null; // local dates of the paired meetings
  to: string | null;
  words: { captions: number; bee: number };
  minWords: number;
  tolerance: { per100: number; relative: number };
  habits: InstrumentHabit[];
  claim: InstrumentClaim;
  note: string;
}
// "partly-started": nothing dropped yet, some drilled habit's after period has started (its first
// drill) and another drilled habit is not drilled yet.
export const TRANSFER_CLAIMS = ["all-dropped-control-flat", "dropped-control-flat", "dropped-control-dropped", "dropped-control-unclear", "partly-started", "not-drilled-yet", "no-drop-yet"] as const;
export type TransferClaim = (typeof TRANSFER_CLAIMS)[number];

// Conversation settings (src/hub/settings.ts): where a Bee conversation happened, so the coach
// compares like with like. A secondary view: the pre-registered transfer check never uses it.
export const CONVERSATION_SETTINGS = ["meeting", "work", "casual"] as const;
export type ConversationSetting = (typeof CONVERSATION_SETTINGS)[number];
// The words a person sees for each setting.
export const SETTING_NAME: Record<ConversationSetting, string> = { meeting: "Meeting", work: "Work talk", casual: "Casual" };
// Why the setting was picked (codes, never text from the conversation):
//   "you"              the wearer set it (POST /api/sessions/<id>/setting); it wins over every rule
//   "captions"         a meeting-captions session
//   "paired-captions"  a Bee conversation that a meeting-captions session matches by time
//   "calendar"         it overlaps a calendar event
//   "work-hours"       a weekday inside the work hours, with 2-4 speakers ("speakers")
//   "weekend" | "outside-work-hours" | "speakers-out-of-range"   why it is casual
//   "speakers-unknown" no speaker count: casual, with low confidence
export type SettingReason = "you" | "captions" | "paired-captions" | "calendar" | "work-hours" | "speakers" | "weekend" | "outside-work-hours" | "speakers-out-of-range" | "speakers-unknown";
export interface SettingTag {
  setting: ConversationSetting;
  source: "auto" | "you";
  confidence: "high" | "low"; // low: casual in work hours only because the speaker count was missing or outside 2-4
  reasons: SettingReason[];
}
// POST /api/sessions/<id>/setting (a stats session id, a recap's conversationId or a recap id)
export interface SettingRequest {
  setting: ConversationSetting | null; // null clears the wearer's choice (back to the automatic one)
}
export interface SettingResponse {
  id: string;
  tag: SettingTag;
  recapIds: string[]; // recaps of this conversation, which now show this setting
}
// One setting's habit rates (per 100 of the wearer's English words; null with too little speech).
export interface SettingRates {
  setting: ConversationSetting;
  name: string;
  sessions: number;
  words: number;
  enough: boolean; // words >= minWords
  per100: { hedges: number | null; "filler:like": number | null; vague: number | null; restart: number | null };
}
export interface SettingPeriodSide {
  sessions: number;
  words: number;
  count: number;
  per100: number;
}
// A practised habit before and after its first practice, within one setting. Never a verdict.
export interface SettingBeforeAfter {
  setting: ConversationSetting;
  name: string;
  before: SettingPeriodSide;
  after: SettingPeriodSide;
  enough: boolean; // both sides have minWords
  deltaPer100: number | null; // only when enough
}
// GET /api/settings?source=bee|all
export interface SettingsResponse extends Labelled {
  generatedAt: string;
  source: SourceSel;
  note: string;
  minWords: number;
  workHours: { start: string; end: string; days: string; tz: string | null };
  sessions: { id: string; kind: "conversation" | "meeting" | "voice_note"; date: string; startMs: number; words: number; tag: SettingTag }[];
  rates: SettingRates[];
  practised: { habit: string; label: string; cutoverAt: number | null; bySetting: SettingBeforeAfter[] }[];
  // One plain line for the TV's Progress screen ("By setting · Unsure words: work talk 2.1 → 1.4 ·
  // casual: too little speech"), or null when no setting has enough speech on both sides.
  line: string | null;
}

// GET /api/brief
export interface Brief {
  dataLabel: string;
  generatedAt: string;
  event: { title: string; startsAt: string; startsInMin: number | null; date: string; source: string } | null;
  eventNote: string | null;
  topHabit: { key: "hedges" | "vague" | "fillers" | "restarts"; label: string; per100: number; count: number; words: number; range: string; source: SourceSel } | null;
  warmup: CardView | null;
  nudge: string;
}

// v2: live coaching (packet A, src/hub/live/**)

// The rules that can nudge. fast-rate is off by default.
export type NudgeRule = "hedge-streak" | "like-streak" | "monologue" | "fast-rate";
export const NUDGE_RULES = ["hedge-streak", "like-streak", "monologue", "fast-rate"] as const satisfies readonly NudgeRule[];

export type WristChannel = "bee-todo" | "replay" | "off";

// Live coaching mode: opt-in wrist nudges. Off by default; turning it on auto-expires.
export interface LiveMode {
  enabled: boolean;
  since: number | null; // when it was turned on
  expiresAt: number | null; // since + minutes (default 60, max 180)
  changedAt: number | null;
  by: string | null; // "alexa" | "mcp" | "tv" | "phone" | "http" | "demo" | "auto"
  reason: "default" | "on" | "off" | "expired" | "wrist-down";
  rules: Record<NudgeRule, boolean>;
  quietHours: { startHour: number; endHour: number }; // local hours, 22 -> 8
  warmupMs: number; // no nudge in the first 60 s of a conversation
  cooldownMs: number; // 3 min between any two nudges
  ruleCooldownMs: number; // 10 min between two nudges of the same rule
  capPerHour: number; // 6
  capPerDay: number; // 20
  sent: { lastHour: number; today: number };
}
// POST /api/live/mode
export interface LiveModeRequest {
  enabled: boolean;
  minutes?: number; // 1-180, default 60 (ignored when enabled is false)
  by?: string;
  rules?: Partial<Record<NudgeRule, boolean>>;
}
export interface LiveModeResponse {
  mode: LiveMode;
  narration: string; // TTS-ready
}

export interface HabitCounts {
  hedges: number;
  likes: number; // "like" as a filler
  fillers: number; // every filler, including like
  vague: number;
  restarts: number;
}
// One rule's current value against its threshold.
export interface RuleState {
  rule: NudgeRule;
  value: number;
  threshold: number;
  unit: "count" | "ms" | "wpm";
  over: boolean; // value >= threshold
}

// The rolling state of the current Bee conversation. Wearer metrics only: other speakers appear as
// counts. No transcript text.
export interface LiveWindow {
  conversationId: string; // Bee conversation_uuid (demo: "demo-...")
  startedAt: number;
  updatedAt: number;
  replay: boolean;
  lang: "en" | "fr" | "mixed";
  wearer: { lines: number; words: number; talkMs: number; wpm: number | null };
  others: { lines: number; words: number };
  talkShare: number | null; // wearer words / all words, 0..1
  monologue: { currentMs: number; longestMs: number };
  pauses: { count: number; longestMs: number }; // gaps >= 1 s inside a wearer turn (from Bee timing)
  recent: HabitCounts & { windowMs: number }; // the last LIVE_WINDOW_RECENT_MS
  totals: HabitCounts;
  skipped: { frenchLines: number; drillLines: number };
  rules: RuleState[];
}

// Latency hops of one nudge, in this order (NUDGE_HOP_ORDER):
//   spokenAt   end of the wearer line that crossed the threshold (Bee spoken_at + duration)
//   beeAt      the hub received Bee's wearer tag for that line (its text became usable)
//   detectedAt the rule fired and the policy allowed a nudge
//   todoAt     `bee todos create` returned (null if the wrist call failed)
//   alarmAt    the to-do's alarm time: the Watch buzzes then (null if the wrist call failed)
export interface NudgeHops {
  spokenAt: number;
  beeAt: number;
  detectedAt: number;
  todoAt: number | null;
  alarmAt: number | null;
}
export const NUDGE_HOP_ORDER = ["spokenAt", "beeAt", "detectedAt", "todoAt", "alarmAt"] as const satisfies readonly (keyof NudgeHops)[];

export interface Nudge {
  id: string; // "ndg_..."
  conversationId: string;
  rule: NudgeRule;
  text: string; // the wrist text: <= WRIST_TEXT_MAX chars, starts "[coach] ", never transcript text
  evidence: RuleState & { windowMs: number | null; expected: number | null }; // expected = baseline count for the window
  hops: NudgeHops;
  latencyMs: { bee: number; detect: number; todo: number | null; total: number | null }; // beeAt-spokenAt, detectedAt-beeAt, todoAt-detectedAt, alarmAt-spokenAt
  wrist: { channel: WristChannel; status: "scheduled" | "failed" | "replay"; todoId: string | null; leadMs: number; error: string | null };
  replay: boolean;
}

export type NudgeSkipReason = "off" | "warmup" | "quiet-hours" | "drill-active" | "cooldown" | "rule-cooldown" | "cap-hour" | "cap-day" | "wrist-down";
export interface NudgeSkipped {
  id: string; // "skp_..."
  conversationId: string;
  rule: NudgeRule;
  reason: NudgeSkipReason;
  detail: string;
  at: number;
  retryAfterMs: number | null; // when the suppression lifts (cooldowns, caps), else null
  evidence: RuleState & { windowMs: number | null; expected: number | null };
  replay: boolean;
}

export interface WristStatus {
  channel: WristChannel;
  healthy: boolean;
  failures: number; // consecutive; the circuit opens at 3
  circuitOpenUntil: number | null;
  leadMs: number; // alarm lead after the to-do is created
  pendingTodos: number; // "[coach]" to-dos awaiting cleanup
}
export interface LiveBaseline {
  source: string; // e.g. "bee week (non-drill conversations)"
  range?: "week" | "all"; // additive: this week, or every Bee conversation when the week has too few words
  words: number;
  hedgesPer100: number;
  likesPer100: number;
  fillersPer100: number;
  wpm: number | null;
}

// GET /api/live
export interface LiveState extends Labelled {
  mode: LiveMode;
  conversation: LiveWindow | null; // the conversation in progress, or null
  drillActive: boolean; // a drill card is open: nudges are suppressed and drill lines skipped
  baseline: LiveBaseline | null;
  wrist: WristStatus;
  lastNudge: Nudge | null;
  recentNudges: Nudge[]; // newest first, at most 10
  recentSkips: NudgeSkipped[]; // newest first, at most 10
  lastRecapId: string | null;
}

export interface ConversationStarted {
  conversationId: string;
  startedAt: number;
  replay: boolean;
}
export interface ConversationEnded {
  conversationId: string;
  startedAt: number;
  endedAt: number;
  reason: "bee-state" | "idle" | "new-conversation" | "demo";
  wearerWords: number;
  otherLines: number;
  recap: "pending" | "skipped-short" | "skipped-french";
  replay: boolean;
}

export interface RecapHabit {
  key: string; // habit key: "hedges" | "filler:like" | "fillers" | "vague" | "restart"
  label: string;
  count: number;
  per100: number;
  baselinePer100: number | null;
  verdict: "better" | "typical" | "worse" | "no-baseline";
}
export interface Recap extends Labelled {
  id: string; // "rcp_..."
  conversationId: string;
  startedAt: number;
  endedAt: number;
  durationMs: number;
  createdAt: number;
  replay: boolean;
  metrics: {
    wearerWords: number;
    wpm: number | null;
    baselineWpm: number | null;
    talkShare: number | null;
    longestMonologueMs: number;
    pauses: { count: number; longestMs: number };
    habits: RecapHabit[];
    // The setting whose usual rates `baselinePer100` are ("against your usual 1.6 in meetings"), or
    // null/absent when the overall usual was used (the setting had too little speech). Additive.
    baselineSetting?: ConversationSetting | null;
  };
  // Where this conversation happened (the wearer's choice when set, else the automatic tag). Additive.
  setting?: SettingTag | null;
  headline: string; // one line for the TV
  // One wearer moment (the wearer's own words, <= RECAP_MOMENT_MAX_WORDS) and its rephrase.
  moment: { text: string; at: number; habit: string; rephrase: string } | null;
  narration: string; // TTS-ready (Alexa, MCP, simulator)
  wristText: string; // <= WRIST_TEXT_MAX chars
  phrasing: "template" | "llm";
  nudges: { sent: number; skipped: number };
  delivery: { wrist: "scheduled" | "failed" | "replay" | "off"; todoId: string | null };
}
// GET /api/recaps?limit=10 (newest first; limit 1-50)
export interface RecapList extends Labelled {
  recaps: Recap[];
}

// GET /api/coach/now: deterministic narration (no model call in the request path).
export interface CoachNow extends Labelled {
  generatedAt: number;
  basis: "live" | "recap" | "week"; // what the narration leads with
  narration: string; // TTS-ready, <= 4 sentences: the lead, the first signal (only when there is one), the week, live coaching
  mode: LiveMode;
  live: LiveWindow | null;
  lastRecap: { id: string; endedAt: number; headline: string; setting?: ConversationSetting | null } | null; // setting: additive
  week: { words: number; hedgesPer100: number; likesPer100: number; vaguePer100: number; topHabit: { key: string; label: string; per100: number } | null };
  drills: { dueNow: number; nextCardId: string | null };
  transferHeadline: string | null;
}

// POST /api/demo/live (demo only): replay a scripted Bee conversation for the synthetic wearer.
export type DemoLiveScript = "story" | "monologue" | "short";
export interface DemoLiveRequest {
  script?: DemoLiveScript; // default "story"
}
export interface DemoLiveResponse {
  replay: true;
  script: DemoLiveScript;
  conversationId: string;
  description: string;
  pace: number;
  steps: { atMs: number; what: string }[]; // real ms after the call (already scaled by pace)
}

// v2: practice and the mirror (packet B, src/hub/mirror.ts, web/phone, tv/*)

export type VolumeBand = "quiet" | "ok" | "loud";
// One phone meter frame, 10 Hz. Room-scoped: mic -> hub -> that room's screens only.
export interface PracticeMeters {
  takeId: string;
  frame: number; // 0, 1, 2... per take
  t: number; // ms since the take started
  at: number; // hub-clock ms (phone clock + welcome offset)
  rmsDbfs: number; // -100..0
  band: VolumeBand;
  voiced: boolean;
  pitchHz: number | null; // YIN, 70-400 Hz; null when unvoiced
  pitchRangeSt: number; // rolling range over the last 5 s, semitones
  monotone: boolean; // pitchRangeSt < 3
  wpm: number | null; // syllable-rate estimate over the last 5 s
  pause: { active: boolean; currentMs: number; count: number }; // pauses >= 250 ms
  caption: string | null; // the speaker's own interim words (Web Speech), never persisted
  from?: string; // added by the hub relay: the mic's clientId
}
export type PracticeFlag = "quiet" | "loud" | "monotone" | "fast" | "slow" | "few-pauses";
// End of a practice take: mic sends it as an app frame; the hub publishes practice.summary.
export interface PracticeSummary {
  takeId: string;
  room: string; // bridge room code
  from: string; // mic clientId
  startedAt: number;
  endedAt: number;
  durationMs: number;
  frames: number;
  volume: { meanDbfs: number; p10Dbfs: number; p90Dbfs: number; quietShare: number; loudShare: number };
  pitch: { medianHz: number | null; rangeSt: number; voicedShare: number; monotone: boolean };
  rate: { wpm: number | null };
  pauses: { count: number; perMin: number; meanMs: number; longestMs: number };
  words: number | null; // Web Speech word count (no text)
  flags: PracticeFlag[];
  provisional: true; // phone-measured; Bee remains the input of record for real speech
}

export type MirrorView = "week" | "transfer" | "drill" | "live" | "practice" | "recap";
export interface MirrorFocus {
  view: MirrorView;
  by: string;
  reason: string | null;
  recapId: string | null;
  takeId: string | null;
  room?: string | null; // the bridge room of the phone mic that asked: only that room's screens follow it
}
// POST /api/demo/mirror (demo only)
export type DemoMirrorScript = "practice-take" | "focus";
export interface DemoMirrorRequest {
  script?: DemoMirrorScript; // default "practice-take"
  view?: MirrorView; // for "focus"
  room?: string; // a room code; default every room
}
export interface DemoMirrorResponse {
  replay: true;
  script: DemoMirrorScript;
  takeId: string | null;
  frames: number;
  hz: number;
  durationMs: number;
  rooms: number;
}

// v2: Alexa and MCP (packet C, src/alexa/**, src/mcp/**)

export type AlexaIntent =
  | "LaunchRequest"
  | "StartDrillIntent"
  | "AttemptIntent"
  | "HowDidIDoIntent"
  | "HowAmIDoingIntent"
  | "LiveCoachOnIntent"
  | "LiveCoachOffIntent"
  | "DidItTransferIntent"
  | "AMAZON.NextIntent"
  | "AMAZON.HelpIntent"
  | "AMAZON.StopIntent"
  | "AMAZON.CancelIntent"
  | "AMAZON.FallbackIntent"
  | "SessionEndedRequest";

// MCP tools (Streamable HTTP, stateless, at /mcp). Each maps 1:1 to one hub route; the result is
// `content: [{type:"text", text: <narration>}]` plus `structuredContent: <the route's JSON>`, and
// `isError: true` when the route answers >= 400.
export const MCP_TOOLS = [
  { name: "start_drill", route: "POST /api/session/start", args: "{ size?: number }" },
  { name: "submit_attempt", route: "POST /api/attempt", args: "{ text: string, card_id?: string }" },
  { name: "get_verdict", route: "GET /api/attempts/<id>", args: "{ attempt_id: string }" },
  { name: "drill_status", route: "GET /api/session", args: "{}" },
  { name: "next_card", route: "POST /api/session/next", args: "{}" },
  { name: "end_drill", route: "POST /api/session/end", args: "{}" },
  { name: "how_am_i_doing", route: "GET /api/coach/now", args: "{}" },
  { name: "habit_stats", route: "GET /api/stats", args: "{ range?: string, source?: \"bee\" | \"all\" }" },
  { name: "did_it_transfer", route: "GET /api/transfer", args: "{ habit?: string }" },
  { name: "pre_meeting_brief", route: "GET /api/brief", args: "{}" },
  { name: "live_coach", route: "POST /api/live/mode", args: "{ enabled: boolean, minutes?: number }" },
  { name: "last_recap", route: "GET /api/recaps?limit=1", args: "{}" },
] as const;
export type McpToolName = (typeof MCP_TOOLS)[number]["name"];

// v2: health and plugins

export type PluginStatus = "stub" | "ready" | "degraded" | "off";
export interface PluginInfo {
  name: string;
  owner: string; // "lead" | "packet A" | "packet B" | "packet C"
  status: PluginStatus;
  prefixes: string[];
  routes: string[]; // "METHOD /path" ("<id>" marks a parameter)
  topics?: string[]; // topics it publishes or relays
  note?: string;
}
// GET /api/health (v2 additions; the v1 fields remain)
export interface HealthV2 {
  ok: true;
  contractVersion: typeof CONTRACT_VERSION;
  mode: "live" | "demo";
  dataLabel: string;
  fixtureV2: boolean;
  publicBaseUrl: string | null;
  plugins: PluginInfo[];
  gate: { publicRoutes: string[]; pairToken: "env" | "generated"; mcpToken: "env" | "generated" };
  ws: string;
  sse: string;
  // Display masking of private terms (src/hub/mask.ts): "on (N terms)" or "off". Never a term.
  // Additive: older hubs omit it.
  masking?: string;
}

// Coach thresholds: the fenced JSON block at the end of coach/principles.template.md (or the
// private coach/principles.local.md), read by packet A.
export interface CoachThresholds {
  version: 1;
  rate: { wpmSlow: number; wpmFast: number; fastRateNudge: boolean };
  pause: { minPauseMs: number; longPauseMs: number };
  volume: { quietDbfs: number; loudDbfs: number };
  pitch: { minHz: number; maxHz: number; monotoneSemitones: number };
  hedges: { streakMin: number; windowMs: number; expectedMultiplier: number };
  like: { streakMin: number; windowMs: number; expectedMultiplier: number };
  monologue: { nudgeMs: number };
  recap: { minWearerWords: number; momentMaxWords: number; idleEndMs: number };
}

// Payloads by topic (besides seq and at)

export interface TopicPayloads {
  "session.started": { session: DrillSession };
  "card.open": { card: CardView; by: string; sessionId: string | null; deck: DeckSummary };
  "attempt.provisional": { attempt: Attempt; card: CardView };
  "attempt.status": { attemptId: string; cardId: string; status: "polling"; reason: string };
  "attempt.verified": { attemptId: string; cardId: string; status: "verified" | "unverified"; via: "stream" | "poll" | null; speakerScore: number | null; latencyMs: number | null; beeText: string | null; replay: boolean; reason: string };
  "attempt.graded": { attempt: Attempt; card: CardView; deck: DeckSummary };
  "stats.updated": { dataLabel: string; practiceToday: PracticeCounts; weekPer100: { words: number; hedges: number; vague: number; fillers: number; restarts: number }; transferHeadline: string | null; deck: DeckSummary };
  "session.ended": { summary: SessionSummary | null };
  "conversation.started": ConversationStarted;
  "live.window": { window: LiveWindow };
  "nudge.sent": { nudge: Nudge };
  "nudge.skipped": { skip: NudgeSkipped };
  "conversation.ended": ConversationEnded;
  "recap.ready": { recap: Recap };
  "live.mode": { mode: LiveMode };
  "practice.summary": { summary: PracticeSummary };
  "mirror.focus": MirrorFocus;
}
export interface Sequenced {
  seq: number;
  at: number;
}
// A sequenced event as it arrives: WS `{type:"app", topic, payload}`, SSE `event:/id:/data:`.
export type HubEventFrame<T extends SequencedTopic = SequencedTopic> = { [K in T]: { topic: K; payload: TopicPayloads[K] & Sequenced } }[T];
// Room-scoped frames carry no seq.
export interface RoomFrame {
  topic: "practice.meters";
  payload: PracticeMeters;
}
